package com.pranit.productsupport.bff.client;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import java.io.IOException;import java.time.Duration;import java.net.http.HttpClient;import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpHeaders;import org.springframework.http.HttpMethod;import org.springframework.http.MediaType;import org.springframework.http.ResponseEntity;import org.springframework.http.client.JdkClientHttpRequestFactory;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class CoreApiClient {private final RestClient client;private final ObjectMapper mapper;public CoreApiClient(RestClient.Builder builder,ObjectMapper mapper,@Value("${app.core-service-url}") String url){HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();JdkClientHttpRequestFactory factory=new JdkClientHttpRequestFactory(http);factory.setReadTimeout(Duration.ofSeconds(8));this.client=builder.baseUrl(url).requestFactory(factory).build();this.mapper=mapper;}
 public ResponseEntity<JsonNode> forward(HttpMethod method,String path,Object body,String authorization,Map<String,String> headers){RestClient.RequestBodySpec spec=client.method(method).uri(path).headers(h->{h.setAccept(java.util.List.of(MediaType.APPLICATION_JSON));if(authorization!=null&&!authorization.isBlank())h.set(HttpHeaders.AUTHORIZATION,authorization);if(headers!=null)headers.forEach(h::set);if(body!=null)h.setContentType(MediaType.APPLICATION_JSON);});if(body!=null)spec.body(body);return spec.exchange((request,response)->{JsonNode node=null;try{if(response.getBody()!=null)node=mapper.readTree(response.getBody());}catch(IOException ignored){}return ResponseEntity.status(response.getStatusCode()).contentType(MediaType.APPLICATION_JSON).body(node);});}
 public ResponseEntity<JsonNode> forwardRaw(String path,byte[] body,String signature){return client.post().uri(path).contentType(MediaType.APPLICATION_JSON).header("X-Razorpay-Signature",signature==null?"":signature).body(body).exchange((request,response)->{JsonNode node=null;try{if(response.getBody()!=null)node=mapper.readTree(response.getBody());}catch(IOException ignored){}return ResponseEntity.status(response.getStatusCode()).contentType(MediaType.APPLICATION_JSON).body(node);});}
}
